def iter_graphemes(text: str):
    """Iterate over the graphemes of a string."""
    if not text:
        return

    import unicodedata

    grapheme = ""
    for char in text:
        if (
            unicodedata.category(char).startswith("M")
            or char == "\u200d"
            or "\u1F1E6" <= char <= "\u1F1FF"
        ) and grapheme:
            grapheme += char
        else:
            if grapheme:
                yield grapheme
            grapheme = char
    if grapheme:
        yield grapheme


def set_cell_size(text: str, total: int) -> str:
    """Set the length of a string to fit within given number of cells."""

    if total <= 0:
        return ""

    graphemes = list(iter_graphemes(text))
    current_width = 0
    result_graphemes = []

    for grapheme in graphemes:
        grapheme_width = sum(get_character_cell_size(c) for c in grapheme)
        if current_width + grapheme_width > total:
            break
        result_graphemes.append(grapheme)
        current_width += grapheme_width

    result = "".join(result_graphemes)
    if current_width < total:
        result += " " * (total - current_width)

    return result

